// Package api wires audit-core's scoped read and ingest endpoints.
// Machine writes are limited to a configured source-plane allowlist. Reads
// require an audience-bound service principal plus a signed v3 user/org
// delegation generated by the authenticated gateway boundary.
package api

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strconv"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/rs/zerolog/log"

	"github.com/triodelab/controlplane/audit-core/internal/events"
	"github.com/triodelab/controlplane/audit-core/internal/store"
)

type API struct {
	store       eventStore
	credentials []serviceCredential
	nonces      *delegationNonceCache
	readiness   func(context.Context) Readiness
}

type eventStore interface {
	ListAudit(context.Context, store.AuditFilter) ([]store.AuditRow, error)
	ListUsage(context.Context, store.UsageFilter) ([]store.UsageRow, error)
	SummariseUsage(context.Context, string, time.Time, time.Time) ([]store.UsageSummary, error)
	InsertAuditFromSource(context.Context, *events.AuditEvent, string) (bool, error)
	InsertUsageFromSource(context.Context, *events.UsageEvent, string) (bool, error)
}

type ConsumerReadiness struct {
	Consumer    string    `json:"consumer"`
	Ready       bool      `json:"ready"`
	Pending     uint64    `json:"pending"`
	AckPending  int       `json:"ack_pending"`
	Redelivered int       `json:"redelivered"`
	LastAckAt   time.Time `json:"last_ack_at,omitempty"`
}

type NATSBusReadiness struct {
	Name            string            `json:"name"`
	Connected       bool              `json:"connected"`
	SubscriberReady bool              `json:"subscriber_ready"`
	Audit           ConsumerReadiness `json:"audit"`
	Usage           ConsumerReadiness `json:"usage"`
}

func (r NATSBusReadiness) Ready() bool {
	return r.Name != "" && r.Connected && r.SubscriberReady && r.Audit.Ready && r.Usage.Ready
}

type Readiness struct {
	DatabaseConnected bool               `json:"database_connected"`
	NATSBuses         []NATSBusReadiness `json:"nats_buses"`
	DeliveryMode      string             `json:"delivery_mode"`
	LagMetric         string             `json:"lag_metric"`
}

func (r Readiness) Ready() bool {
	if !r.DatabaseConnected || len(r.NATSBuses) == 0 {
		return false
	}
	for _, bus := range r.NATSBuses {
		if !bus.Ready() {
			return false
		}
	}
	return true
}

func New(s eventStore, rawCredentials string, readiness ...func(context.Context) Readiness) (*API, error) {
	credentials, err := parseServiceCredentialRegistry(rawCredentials)
	if err != nil {
		return nil, err
	}
	provider := func(context.Context) Readiness { return Readiness{} }
	if len(readiness) > 0 && readiness[0] != nil {
		provider = readiness[0]
	}
	return &API{
		store:       s,
		credentials: credentials,
		nonces:      newDelegationNonceCache(100_000),
		readiness:   provider,
	}, nil
}

func (a *API) Mount(r chi.Router) {
	r.Get("/healthz", a.healthz)
	r.Get("/readyz", a.readyz)

	r.Route("/v1", func(r chi.Router) {
		r.Use(a.internalAuth)
		r.Get("/audit", a.listAudit)
		r.Post("/audit", a.ingestAudit)
		r.Get("/usage", a.listUsage)
		r.Post("/usage", a.ingestUsage)
		r.Get("/usage/summary", a.summariseUsage)
	})
}

func (a *API) ingestUsage(w http.ResponseWriter, r *http.Request) {
	body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "failed to read body"})
		return
	}
	event, err := events.DecodeUsage(body)
	if err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
		return
	}
	authorization, authorized := serviceAuthorizationFromContext(r.Context())
	if !authorized || authorization.Scope != "audit:write" ||
		!authorization.AllowsPlane(event.Plane) || event.Producer != authorization.Principal {
		writeJSON(w, http.StatusForbidden, map[string]string{"error": "usage producer authority denied"})
		return
	}
	inserted, err := a.store.InsertUsageFromSource(r.Context(), event, "http:"+authorization.Principal)
	if errors.Is(err, store.ErrUsageEventConflict) {
		writeJSON(w, http.StatusConflict, map[string]any{"error": map[string]string{
			"code": "usage_event_conflict", "message": "event_id already exists with a different payload",
		}})
		return
	}
	if err != nil {
		log.Error().Err(err).Str("org_id", event.OrgID).Msg("ingestUsage: insert failed")
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "insert failed"})
		return
	}
	status := http.StatusAccepted
	if !inserted {
		status = http.StatusOK
	}
	writeJSON(w, status, map[string]any{"data": map[string]bool{"accepted": true, "duplicate": !inserted}})
}

func (a *API) readyz(w http.ResponseWriter, r *http.Request) {
	status := a.readiness(r.Context())
	httpStatus := http.StatusOK
	if !status.Ready() {
		httpStatus = http.StatusServiceUnavailable
	}
	writeJSON(w, httpStatus, map[string]any{
		"status":       map[bool]string{true: "ready", false: "degraded"}[status.Ready()],
		"dependencies": status,
	})
}

func (a *API) healthz(w http.ResponseWriter, _ *http.Request) {
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte(`{"status":"ok"}`))
}

func (a *API) internalAuth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		authorization, failure := authorizeServiceRequest(r, a.credentials, a.nonces, time.Now())
		if failure != nil {
			writeJSON(w, failure.Status, map[string]string{"error": failure.Message})
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), serviceAuthorizationContextKey{}, authorization)))
	})
}

type serviceAuthorizationContextKey struct{}

func serviceAuthorizationFromContext(ctx context.Context) (serviceAuthorization, bool) {
	authorization, ok := ctx.Value(serviceAuthorizationContextKey{}).(serviceAuthorization)
	return authorization, ok
}

func (a *API) listAudit(w http.ResponseWriter, r *http.Request) {
	orgID := r.URL.Query().Get("org_id")
	if orgID == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "org_id required"})
		return
	}

	filter := store.AuditFilter{
		OrgID:  orgID,
		Since:  parseTime(r.URL.Query().Get("since")),
		Until:  parseTime(r.URL.Query().Get("until")),
		Event:  r.URL.Query().Get("event"),
		UserID: r.URL.Query().Get("user_id"),
		Limit:  parseInt(r.URL.Query().Get("limit"), 100),
	}
	rows, err := a.store.ListAudit(r.Context(), filter)
	if err != nil {
		log.Error().Err(err).Str("org_id", orgID).Msg("listAudit failed")
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "query failed"})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"data": rows, "meta": map[string]any{
		"count": len(rows),
		"limit": filter.Limit,
	}, "error": nil})
}

func (a *API) listUsage(w http.ResponseWriter, r *http.Request) {
	orgID := r.URL.Query().Get("org_id")
	if orgID == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "org_id required"})
		return
	}
	filter := store.UsageFilter{
		OrgID: orgID,
		Since: parseTime(r.URL.Query().Get("since")),
		Until: parseTime(r.URL.Query().Get("until")),
		Plane: r.URL.Query().Get("plane"),
		Op:    r.URL.Query().Get("op"),
		Limit: parseInt(r.URL.Query().Get("limit"), 200),
	}
	rows, err := a.store.ListUsage(r.Context(), filter)
	if err != nil {
		log.Error().Err(err).Str("org_id", orgID).Msg("listUsage failed")
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "query failed"})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"data": rows, "meta": map[string]any{
		"count": len(rows),
		"limit": filter.Limit,
	}, "error": nil})
}

func (a *API) summariseUsage(w http.ResponseWriter, r *http.Request) {
	orgID := r.URL.Query().Get("org_id")
	if orgID == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "org_id required"})
		return
	}
	rows, err := a.store.SummariseUsage(
		r.Context(), orgID,
		parseTime(r.URL.Query().Get("since")),
		parseTime(r.URL.Query().Get("until")),
	)
	if err != nil {
		log.Error().Err(err).Str("org_id", orgID).Msg("summariseUsage failed")
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "query failed"})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"data": rows, "meta": map[string]any{
		"count": len(rows),
	}, "error": nil})
}

// ingestAudit accepts a single AuditEvent JSON body from an internal
// service caller (e.g. the velionv2 BFF) and persists it via the same
// path the NATS subscriber uses. Validation and normalization
// (occurred_at default, outcome default "ok", required-field checks)
// are performed by AuditEvent.Validate(), which DecodeAudit already
// calls — so we reuse that same normalise+validate function here to
// keep both paths identical.
func (a *API) ingestAudit(w http.ResponseWriter, r *http.Request) {
	body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20)) // 1 MiB cap
	if err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "failed to read body"})
		return
	}
	ev, err := events.DecodeAudit(body)
	if err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
		return
	}
	authorization, authorized := serviceAuthorizationFromContext(r.Context())
	if !authorized || authorization.Scope != "audit:write" ||
		!authorization.AllowsPlane(ev.Plane) || ev.Producer != authorization.Principal {
		writeJSON(w, http.StatusForbidden, map[string]string{"error": "audit producer authority denied"})
		return
	}
	inserted, err := a.store.InsertAuditFromSource(
		r.Context(), ev, "http:"+authorization.Principal,
	)
	if errors.Is(err, store.ErrAuditEventConflict) {
		writeJSON(w, http.StatusConflict, map[string]any{"error": map[string]string{
			"code": "audit_event_conflict", "message": "event_id already exists with a different payload",
		}})
		return
	}
	if err != nil {
		log.Error().Err(err).Str("org_id", ev.OrgID).Msg("ingestAudit: insert failed")
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "insert failed"})
		return
	}
	log.Info().Str("org_id", ev.OrgID).Str("plane", ev.Plane).Str("event", ev.Event).
		Msg("ingestAudit: persisted")
	status := http.StatusAccepted
	if !inserted {
		status = http.StatusOK
	}
	writeJSON(w, status, map[string]any{"data": map[string]bool{"accepted": true, "duplicate": !inserted}})
}

func writeJSON(w http.ResponseWriter, status int, body any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(body)
}

func parseTime(s string) time.Time {
	if s == "" {
		return time.Time{}
	}
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return time.Time{}
	}
	return t
}

func parseInt(s string, fallback int) int {
	if s == "" {
		return fallback
	}
	v, err := strconv.Atoi(s)
	if err != nil || v <= 0 {
		return fallback
	}
	return v
}
